{
    bound_site_trace = getenv("SAMALTAK_FFI_SITE_TRACE") != NULL;
    if (bound_site_trace) {
        install_trace_function(trace_bound_primitive, 264);
    }
}

/* FFIPrimitives>>copyName:into: */
size_t copy_name(oop name, uint8_t *buf)
{
    int32_t f;
    uint64_t v;
    uint64_t n;
    int64_t i;
    uint32_t c;
    if (!is_kind_of_string(name)) {
        return 0;
    }
    f = (int32_t)(((*(uint64_t *)name) >> H_FMT_SHIFT) & H_FMT_MASK);
    n = ({
    if (f >= F_BYTES) {
        v = 8 * (uint64_t)(uint32_t)*(uint64_t *)name - (uint64_t)((int32_t)(((*(uint64_t *)name) >> H_FMT_SHIFT) & H_FMT_MASK) - F_BYTES);
    } else {
        if (!((f == F_W32) || (f == 11))) {
            return 0;
        }
        v = 2 * (uint64_t)(uint32_t)*(uint64_t *)name - (uint64_t)(f - F_W32);
    }
    v; });
    if ((n == 0) || (n > 127)) {
        return 0;
    }
    for (i = 0; i <= (int64_t)n - 1; i++) {
        c = string_char_at(name, (uint64_t)i);
        if ((c == 0) || (c > 127)) {
            return 0;
        }
        buf[i] = (uint8_t)c;
    }
    buf[n] = 0;
    return n;
}

/* FFIPrimitives>>describeBoundOwner:arity:into: */
static bool describe_bound_owner(oop owner, int32_t n, ffi_bound_site *desc)
{
    int32_t local;
    int32_t *arity;
    uint64_t entry;
    uint64_t token;
    int32_t slot;
    uint64_t serial;
    uint64_t result_tag;
    memset(&local, 0, sizeof local);
    arity = &local;
    entry = bound_entry(owner, arity);
    if ((entry == 0) || ((entry == FFI_BOUND_REJECTED) || (*arity != n))) {
        return false;
    }
    token = *(uint64_t *)(owner + 16 + 8);
    slot = (int32_t)(((uint64_t)(((int64_t)token) >> 1)) & 4095ULL);
    serial = binding_serials[slot];
    if (serial == 0) {
        return false;
    }
    desc->serial_addr = (uint64_t)(binding_serials + slot);
    desc->serial = serial;
    desc->entry = entry;
    result_tag = (uint64_t)binding_result_tags[slot];
    desc->result_tag = result_tag >= 11 ? 6ULL : result_tag;
    desc->token = token;
    desc->owner_addr = (uint64_t)(binding_owners + slot);
    return true;
}

/* FFIPrimitives>>ensureBindingSession */
static bool ensure_binding_session(void)
{
    uint64_t local;
    uint64_t *nonce;
    if (binding_session != 0) {
        return true;
    }
    memset(&local, 0, sizeof local);
    nonce = &local;
    if (getentropy(nonce, 8) != 0) {
        return false;
    }
    binding_session = (*nonce) & 4611686018427387903ULL & 18446744073709547520ULL;
    if (binding_session == 0) {
        return false;
    }
    register_weak_owners(update_binding_owners, invalidate_bindings);
    return true;
}

